<template>
  <section ref="root" class="story-editor" :class="[{ 'story-editor--fullscreen': fullscreen }, `story-editor--${document.settings.theme}`, `story-editor--${document.settings.density}`]">
    <header class="story-editor__header">
      <div><strong>{{ document.title }}</strong><small>{{ document.messages.length }} 条消息 · {{ document.characters.length - 1 }} 个角色</small></div>
      <div class="story-editor__header-actions"><button @click="$emit('download')">下载 SSP</button><button v-if="!document.settings.previewOnly" @click="moveMode=!moveMode">{{ moveMode ? '完成移动' : '移动' }}</button><button @click="$emit('preview')">沉浸预览</button><button @click="toggleFullscreen">{{ fullscreen ? '退出全屏' : '全屏' }}</button></div>
    </header>
    <div class="story-editor__size"><span>画布宽度</span><input v-model.number="width" type="range" min="360" max="1200" step="20" /></div>
    <main ref="messageList" :style="canvasStyle">
      <div v-if="!document.messages.length" class="empty">还没有消息。请从下方选择角色并开始写作。</div>
      <article v-for="(message,index) in document.messages" :key="message.id" :data-id="message.id" class="story-message" :class="[`story-message--${character(message.characterId)?.position || 'left'}`, { 'story-message--selected': selected.has(message.id), 'story-message--merged': merged(index) }]" @click="selectMessage(message.id)">
        <button v-if="moveMode" class="drag" title="拖动消息">⠿</button>
        <button v-if="showAvatar(index)" class="avatar" @click.stop="selectCharacter(message.characterId)"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><span v-else>{{ character(message.characterId)?.name?.slice(0,1) || '旁' }}</span></button>
        <div class="story-message__content">
          <small v-if="(document.settings.showNames && !merged(index)) || document.settings.showTime"><template v-if="document.settings.showNames && !merged(index)">{{ character(message.characterId)?.name }}<template v-if="document.settings.showQqInEditor && character(message.characterId)?.imUserId"> · {{ character(message.characterId)?.imUserId }}</template></template><template v-if="document.settings.showTime">{{ document.settings.showNames && !merged(index) ? ' · ' : '' }}{{ messageTime(message) }}</template></small>
          <div class="bubble">
            <img v-if="message.kind==='image'" :src="asset(message.asset)" :alt="message.alt || '图片'" />
            <textarea v-else-if="editingId===message.id" ref="editArea" v-model="editText" rows="2" @keydown.enter.exact.prevent="commitEdit(message.id)" @keydown.esc.prevent="cancelEdit" />
            <span v-else>{{ message.text }}</span>
          </div>
          <div v-if="!document.settings.previewOnly" class="message-actions">
            <button v-if="message.kind==='text'" @click.stop="editingId===message.id?commitEdit(message.id):startEdit(message)">{{ editingId===message.id?'确认':'编辑' }}</button>
            <button @click.stop="openInsert(message.id,'above')">上方插入</button><button @click.stop="openInsert(message.id,'below')">下方插入</button><button class="danger" @click.stop="removeSelected(message.id)">删除</button>
          </div>
        </div>
      </article>
    </main>

    <section v-if="!document.settings.previewOnly" class="composer">
      <textarea v-model="draft" rows="2" :placeholder="insertTarget ? `将在所选消息${insertDirection==='above'?'上方':'下方'}插入；每行一条消息` : '每行一条消息；按 Ctrl+Enter 发送'" @keydown.ctrl.enter.prevent="addMessages" />
      <div><button @click="imageInput?.click()">图片</button><button v-if="insertTarget" @click="cancelInsert">取消插入</button><button class="primary" :disabled="!draft.trim()" @click="addMessages">{{ insertTarget ? '插入' : '发送' }}</button></div>
      <input ref="imageInput" hidden type="file" accept="image/*" @change="addImage" />
    </section>

    <nav v-if="!document.settings.previewOnly" class="characters" aria-label="角色选择">
      <button v-for="item in document.characters" :key="item.id" :class="{active:selectedCharacterId===item.id}" @click="characterClick(item)">
        <span class="character-avatar"><img v-if="avatar(item)" :src="avatar(item)" alt="" /><i v-else>{{ item.name.slice(0,1) }}</i></span><small>{{ item.name }}</small><em>{{ positionText(item.position) }}</em>
      </button>
      <button class="character-add" @click="newCharacter">＋<small>新增角色</small></button>
    </nav>

    <Teleport to="body"><div v-if="editingCharacter" class="character-modal" @click.self="editingCharacter=null"><form @submit.prevent="saveCharacter"><h3>编辑角色</h3><label>角色名<input v-model="characterForm.name" maxlength="80" required /></label><label>QQ 号<input v-model="characterForm.imUserId" inputmode="numeric" /></label><label>位置<select v-model="characterForm.position" :disabled="editingCharacter.isNarrator"><option value="left">左侧</option><option value="right">右侧</option><option value="narrator">旁白</option></select></label><label>头像<input type="file" accept="image/*" @change="setAvatar" /></label><div class="avatar-preview"><img v-if="characterForm.avatarUrl" :src="characterForm.avatarUrl" alt="头像预览" /><span v-else>输入 QQ 号后会自动获取头像</span></div><footer><button type="button" @click="editingCharacter=null">取消</button><button v-if="!editingCharacter.isNarrator" type="button" class="danger" @click="deleteCharacter">删除角色</button><button class="primary" type="submit">保存</button></footer></form></div></Teleport>
  </section>
</template>

<script setup lang="ts">
import Sortable from "sortablejs";
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, toRaw, watch } from "vue";
import { createStoryId } from "~/story/model";
import type { StoryArchive, StoryCharacter, StoryMessage, StoryPosition } from "~/story/types";
const props=defineProps<{archive:StoryArchive;assetUrl:(id:string)=>string}>();const emit=defineEmits<{change:[StoryArchive];download:[];preview:[]}>();
const document=computed(()=>props.archive.document);const root=ref<HTMLElement>();const messageList=ref<HTMLElement>();const imageInput=ref<HTMLInputElement>();const editArea=ref<HTMLTextAreaElement[]>();const fullscreen=ref(false);const moveMode=ref(false);const width=ref(document.value.settings.canvasWidth);const selected=reactive(new Set<string>());const selectedCharacterId=ref(document.value.characters.find(c=>!c.isNarrator)?.id||'character-narrator');const editingId=ref('');const editText=ref('');const draft=ref('');const insertTarget=ref('');const insertDirection=ref<'above'|'below'>('below');const editingCharacter=ref<StoryCharacter|null>(null);const characterForm=reactive({name:'',imUserId:'',position:'left' as StoryPosition,avatarUrl:'',localAssetId:''});let sortable:Sortable|null=null;
const canvasStyle=computed(()=>({'--canvas-width':`${width.value}px`,'--bubble-width':`${document.value.settings.bubbleMaxWidth}%`,'--font-size':`${document.value.settings.fontSize}px`}));
function cloneArchive():StoryArchive{return{document:structuredClone(toRaw(document.value)),assets:new Map(toRaw(props.archive.assets))}}function update(mutator:(archive:StoryArchive)=>void){const archive=cloneArchive();mutator(archive);archive.document.updatedAt=new Date().toISOString();emit('change',archive)}
function character(id:string){return document.value.characters.find(c=>c.id===id)}function asset(value?:{id:string;sourceUrl?:string}){return value?(props.archive.assets.has(value.id)?props.assetUrl(value.id):value.sourceUrl||value.id):''}function avatar(c?:StoryCharacter){return asset(c?.avatar)||(c?.imUserId?`/api/editor/avatar/qq/${encodeURIComponent(c.imUserId)}`:'')}function positionText(p:StoryPosition){return p==='right'?'右':p==='narrator'?'旁白':'左'}
function merged(index:number){if(!document.value.settings.mergeMessages||index===0)return false;const current=document.value.messages[index],previous=document.value.messages[index-1],c=character(current.characterId);return current.characterId===previous.characterId&&(!c?.isNarrator||document.value.settings.mergeNarration)}
function mergedWithNext(index:number){if(!document.value.settings.mergeMessages||index>=document.value.messages.length-1)return false;const current=document.value.messages[index],next=document.value.messages[index+1],c=character(current.characterId);return current.characterId===next.characterId&&(!c?.isNarrator||document.value.settings.mergeNarration)}
function showAvatar(index:number){const m=document.value.messages[index],c=character(m.characterId);if(!document.value.settings.showAvatars||(!document.value.settings.showNarratorAvatar&&c?.isNarrator))return false;return document.value.settings.avatarAlignment==='bottom'?!mergedWithNext(index):!merged(index)}
function messageTime(message:StoryMessage){if(message.timeText)return message.timeText;if(!message.time)return '--:--';const value=message.time>10_000_000_000?message.time:message.time*1000;return new Date(value).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}
function selectMessage(id:string){if(!moveMode.value)return;if(selected.has(id))selected.delete(id);else selected.add(id)}function selectCharacter(id:string){selectedCharacterId.value=id}
function startEdit(message:StoryMessage){if(message.kind!=='text')return;editingId.value=message.id;editText.value=message.text;nextTick(()=>editArea.value?.[0]?.focus())}function cancelEdit(){editingId.value='';editText.value=''}function commitEdit(id:string){const value=editText.value.trim();if(!value)return;update(a=>{const m=a.document.messages.find(v=>v.id===id);if(m?.kind==='text')m.text=value});cancelEdit()}
function openInsert(id:string,direction:'above'|'below'){insertTarget.value=id;insertDirection.value=direction;root.value?.querySelector<HTMLTextAreaElement>('.composer textarea')?.focus()}function cancelInsert(){insertTarget.value=''}
function insertionIndex(messages:StoryMessage[]){if(!insertTarget.value)return messages.length;const i=messages.findIndex(m=>m.id===insertTarget.value);return Math.max(0,i+(insertDirection.value==='below'?1:0))}
function addMessages(){const lines=draft.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);if(!lines.length)return;update(a=>{const index=insertionIndex(a.document.messages);const items=lines.map(text=>({id:createStoryId('message'),kind:'text' as const,characterId:selectedCharacterId.value,text,time:0,locallyInserted:true,sourceFingerprint:''}));a.document.messages.splice(index,0,...items)});draft.value='';cancelInsert()}
async function addImage(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;const bytes=new Uint8Array(await file.arrayBuffer());const id=createStoryId('asset');update(a=>{a.assets.set(id,bytes);const index=insertionIndex(a.document.messages);a.document.messages.splice(index,0,{id:createStoryId('message'),kind:'image',characterId:selectedCharacterId.value,asset:{id,mime:file.type||'application/octet-stream',name:file.name},alt:file.name,time:0,locallyInserted:true,sourceFingerprint:''})});input.value='';cancelInsert()}
function removeSelected(id:string){const ids=selected.size&&selected.has(id)?new Set(selected):new Set([id]);if(!confirm(`确定删除 ${ids.size} 条消息吗？`))return;update(a=>a.document.messages=a.document.messages.filter(m=>!ids.has(m.id)));selected.clear()}
function characterClick(item:StoryCharacter){if(selectedCharacterId.value===item.id)openCharacter(item);else selectedCharacterId.value=item.id}function openCharacter(item:StoryCharacter){editingCharacter.value=item;const local=!!item.avatar&&props.archive.assets.has(item.avatar.id);Object.assign(characterForm,{name:item.name,imUserId:item.imUserId,position:item.position,avatarUrl:local?'':item.avatar?.sourceUrl||item.avatar?.id||'',localAssetId:local?item.avatar!.id:''})}
function newCharacter(){const item:StoryCharacter={id:createStoryId('character'),name:'新角色',imUserId:'',position:'left',color:'#64748b',isNarrator:false,isDice:false,hidden:false};editingCharacter.value=item;Object.assign(characterForm,{name:item.name,imUserId:'',position:'left',avatarUrl:'',localAssetId:''})}
async function setAvatar(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const id=createStoryId('asset');const bytes=new Uint8Array(await file.arrayBuffer());update(a=>a.assets.set(id,bytes));characterForm.localAssetId=id;characterForm.avatarUrl=URL.createObjectURL(file)}
function saveCharacter(){if(!editingCharacter.value)return;const id=editingCharacter.value.id;update(a=>{let target=a.document.characters.find(c=>c.id===id);if(!target){target={...editingCharacter.value!};a.document.characters.push(target)}target.name=characterForm.name.trim()||'未命名角色';target.imUserId=characterForm.imUserId.trim();target.position=target.isNarrator?'narrator':characterForm.position;const sourceUrl=characterForm.localAssetId?'':characterForm.avatarUrl||(target.imUserId?`/api/editor/avatar/qq/${encodeURIComponent(target.imUserId)}`:'');target.avatar=characterForm.localAssetId?{id:characterForm.localAssetId,mime:'image/*',name:'头像'}:sourceUrl?{id:sourceUrl,mime:'image/*',sourceUrl,name:'头像'}:undefined;target.avatarSource=characterForm.localAssetId?'upload':target.imUserId?'qq':undefined});selectedCharacterId.value=id;editingCharacter.value=null}
function deleteCharacter(){const target=editingCharacter.value;if(!target||target.isNarrator)return;if(!confirm(`删除角色「${target.name}」及其全部消息？`))return;update(a=>{a.document.characters=a.document.characters.filter(c=>c.id!==target.id);a.document.messages=a.document.messages.filter(m=>m.characterId!==target.id)});selectedCharacterId.value='character-narrator';editingCharacter.value=null}
async function toggleFullscreen(){if(!globalThis.document.fullscreenElement)await root.value?.requestFullscreen();else await globalThis.document.exitFullscreen()}function fullscreenChanged(){fullscreen.value=!!globalThis.document.fullscreenElement}
function initSortable(){sortable?.destroy();if(!messageList.value)return;sortable=Sortable.create(messageList.value,{animation:180,handle:'.drag',disabled:!moveMode.value,onEnd:e=>{if(e.oldIndex==null||e.newIndex==null)return;const order=document.value.messages.map(m=>m.id);const dragged=order[e.oldIndex];const moving=selected.has(dragged)?order.filter(id=>selected.has(id)):[dragged];const remaining=order.filter(id=>!moving.includes(id));let anchor=e.newIndex;if(e.newIndex>e.oldIndex)anchor=Math.max(0,anchor-moving.length+1);remaining.splice(Math.min(anchor,remaining.length),0,...moving);update(a=>{const map=new Map(a.document.messages.map(m=>[m.id,m]));a.document.messages=remaining.map(id=>map.get(id)!).filter(Boolean)})}})}
watch(moveMode,()=>{if(sortable)sortable.option('disabled',!moveMode.value);if(!moveMode.value)selected.clear()});watch(width,v=>update(a=>a.document.settings.canvasWidth=v));watch(()=>props.archive.document.id,()=>{width.value=document.value.settings.canvasWidth;nextTick(initSortable)});onMounted(()=>{initSortable();globalThis.document.addEventListener('fullscreenchange',fullscreenChanged)});onBeforeUnmount(()=>{sortable?.destroy();globalThis.document.removeEventListener('fullscreenchange',fullscreenChanged)});
</script>

<style scoped>
.story-editor{--surface:#101716;--surface2:#182120;--text:#edf3f2;--muted:#97a5a2;--accent:#38bfc8;margin:1rem 0;border-radius:20px;overflow:hidden;background:var(--surface);color:var(--text);box-shadow:0 18px 60px rgba(0,0,0,.2)}.story-editor--light{--surface:#eef2f7;--surface2:#fff;--text:#17202a;--muted:#64748b}.story-editor--fullscreen{position:fixed;inset:0;z-index:9999;border-radius:0;margin:0;display:grid;grid-template-rows:auto auto 1fr auto auto}.story-editor__header{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem 1.2rem;background:rgba(30,40,39,.96)}.story-editor__header>div:first-child{display:grid}.story-editor__header small{color:var(--muted)}.story-editor__header-actions{display:flex;gap:.5rem;flex-wrap:wrap;justify-content:flex-end}.story-editor button{border:0;border-radius:10px;padding:.55rem .75rem;background:#2a3534;color:inherit;cursor:pointer}.story-editor button:hover{filter:brightness(1.15)}.story-editor button.primary{background:#168a92}.story-editor button.danger{color:#ff9b9b}.story-editor__size{display:flex;align-items:center;justify-content:center;gap:.75rem;padding:.45rem;background:rgba(0,0,0,.15);font-size:.8rem;color:var(--muted)}.story-editor__size input{width:min(320px,50vw)}.story-editor main{width:min(var(--canvas-width),100%);margin:auto;min-height:420px;max-height:70vh;overflow:auto;padding:1.3rem clamp(.8rem,3vw,2rem);scrollbar-gutter:stable}.story-editor--fullscreen main{max-height:none}.story-message{display:flex;gap:.7rem;align-items:flex-start;margin:.5rem 0;position:relative;font-size:var(--font-size)}.story-message--merged{margin-top:-.25rem}.story-message--selected{outline:2px solid var(--accent);outline-offset:5px;border-radius:16px}.story-message>.avatar{width:42px;height:42px;border-radius:50%;padding:0;overflow:hidden;flex:0 0 42px;background:#334342}.avatar img,.character-avatar img{width:100%;height:100%;object-fit:cover}.story-message__content{max-width:var(--bubble-width)}.story-message__content>small{display:block;color:var(--muted);margin:0 .35rem .2rem}.bubble{padding:.7rem .95rem;border-radius:18px;background:var(--surface2);white-space:pre-wrap;overflow-wrap:anywhere;min-width:3rem}.bubble>img{display:block;max-width:100%;max-height:65vh;border-radius:12px}.bubble textarea{width:min(560px,60vw);min-height:4.5rem;border:0;outline:0;resize:vertical;background:transparent;color:inherit;font:inherit}.story-message--right{flex-direction:row-reverse;text-align:right}.story-message--right .bubble{background:#174a4e}.story-message--narrator{justify-content:center;text-align:center}.story-message--narrator .bubble{background:#252d2c;color:#c8d1cf;border-radius:10px}.message-actions{display:flex;gap:.25rem;margin-top:.25rem;opacity:0;transition:.15s}.story-message:hover .message-actions,.story-message:focus-within .message-actions{opacity:1}.message-actions button{padding:.25rem .45rem;font-size:.75rem}.drag{cursor:grab;align-self:center;padding:.25rem!important}.composer{display:flex;gap:.65rem;padding:.8rem 1rem;background:rgba(25,34,33,.98)}.composer textarea{flex:1;min-width:0;border:1px solid #42504e;border-radius:15px;background:#293331;color:inherit;padding:.8rem 1rem;resize:none;font:inherit}.composer>div{display:flex;align-items:flex-end;gap:.4rem}.characters{display:flex;gap:.45rem;overflow-x:auto;padding:.75rem 1rem max(.75rem,env(safe-area-inset-bottom));background:#161e1d}.characters>button{display:grid;justify-items:center;gap:.15rem;min-width:70px;background:transparent}.characters>button.active{background:#263938;outline:2px solid var(--accent)}.character-avatar{width:48px;height:48px;border-radius:50%;overflow:hidden;background:#334342;display:grid;place-items:center;font-size:1.2rem}.characters em{font-size:.65rem;color:var(--muted);font-style:normal}.empty{padding:5rem 1rem;text-align:center;color:var(--muted)}.character-modal{position:fixed;inset:0;z-index:10010;display:grid;place-items:center;background:rgba(0,0,0,.68);padding:1rem}.character-modal form{width:min(420px,100%);display:grid;gap:.8rem;padding:1.25rem;border-radius:18px;background:#1c2625;color:#eef2f1}.character-modal h3{margin:0}.character-modal label{display:grid;gap:.3rem}.character-modal input,.character-modal select{padding:.65rem;border:1px solid #465553;border-radius:10px;background:#111817;color:inherit}.character-modal footer{display:flex;justify-content:flex-end;gap:.5rem}.avatar-preview{display:flex;align-items:center;justify-content:center;min-height:80px;color:#98a5a3}.avatar-preview img{width:72px;height:72px;border-radius:50%;object-fit:cover}@media(max-width:650px){.story-editor{border-radius:14px}.story-editor__header{align-items:flex-start;flex-direction:column}.story-editor__size{display:none}.story-editor main{width:100%;max-height:72vh;padding:1rem .75rem}.story-message__content{max-width:82%}.message-actions{opacity:1;overflow-x:auto}.message-actions button{white-space:nowrap}.composer{flex-direction:column}.composer>div{justify-content:flex-end}.bubble textarea{width:60vw}}
.characters{scrollbar-width:none}.characters::-webkit-scrollbar{display:none}
.story-editor--compact .story-message{margin:.25rem 0}.story-editor--compact .bubble{padding:.5rem .75rem}.story-editor--spacious .story-message{margin:.85rem 0}.story-editor--spacious .bubble{padding:.95rem 1.15rem}@media(prefers-color-scheme:light){.story-editor--auto{--surface:#eef2f7;--surface2:#fff;--text:#17202a;--muted:#64748b}}
</style>
